      <main className="flex-grow">
        <Hero onContactClick={openContactModal} />
        <About onContactClick={openContactModal} />
        <Benefits />
        <ResortShowcase isAdmin={isAdmin} />
        <AIPlanner />
        <BudgetTool />
      </main>
      <Footer 
        isAdmin={isAdmin} 
        onToggleAdmin={() => setIsAdmin(!isAdmin)} 
