import React, { useState, useEffect, useRef } from 'react';

interface HeaderProps {
  onContactClick?: (e?: React.MouseEvent) => void;
  isAdmin?: boolean;
}

const LOGO_STORAGE_KEY = 'dream_it_custom_logo_v1';

const Header: React.FC<HeaderProps> = ({ onContactClick, isAdmin = false }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [customLogo, setCustomLogo] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);

    // Load custom logo
    const savedLogo = localStorage.getItem(LOGO_STORAGE_KEY);
    if (savedLogo) setCustomLogo(savedLogo);

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setCustomLogo(base64);
        localStorage.setItem(LOGO_STORAGE_KEY, base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetLogo = () => {
    if (window.confirm("Reset to default brand mark?")) {
      setCustomLogo(null);
      localStorage.removeItem(LOGO_STORAGE_KEY);
    }
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-500 ${isScrolled ? 'bg-glass py-2 shadow-sm border-b border-slate-200/50' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 grid grid-cols-3 items-center">

        {/* Left Spacing / Placeholder */}
        <div className="flex justify-start">
           {isAdmin && customLogo && (
             <button 
              onClick={resetLogo}
              className="text-[10px] font-bold uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1.5"
             >
               <i className="fas fa-undo-alt"></i> Reset Logo
             </button>
           )}
        </div>

        {/* Strategic Logo Placement (Centered) */}
        <div className="flex justify-center relative group">
          <div className="flex flex-col items-center">
            <div className="relative">
              {customLogo ? (
                <img 
                  src={customLogo} 
                  alt="Dream it marketing" 
                  className={`transition-all duration-500 ${isScrolled ? 'h-10 md:h-12' : 'h-16 md:h-20'} object-contain`}
                />
              ) : (
                <div className="flex flex-col items-center">
                   <div className={`flex items-center justify-center rounded-full font-bold text-white transition-all duration-500 shadow-xl ${isScrolled ? 'w-10 h-10 bg-blue-600 text-lg' : 'w-16 h-16 bg-blue-600/90 text-2xl backdrop-blur-md border border-white/20'}`}>
                    D
                  </div>
                  {!isScrolled && (
                    <span className="text-white text-[10px] font-bold uppercase tracking-[0.4em] mt-3 opacity-80">Dream it marketing</span>
                  )}
                </div>
              )}

              {/* Admin Overlay */}
              {isAdmin && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute -right-4 -top-2 w-8 h-8 bg-white text-blue-600 rounded-full shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all opacity-0 group-hover:opacity-100 z-50 border border-slate-100"
                  title="Upload Custom Logo"
                >
                  <i className="fas fa-camera text-xs"></i>
                </button>
              )}
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleLogoUpload} 
                className="hidden" 
                accept="image/*" 
              />
            </div>
          </div>
        </div>

        {/* Action Button */}
        <div className="flex justify-end">
          <button 
            onClick={onContactClick}
            className={`transition-all duration-500 transform hover:scale-105 inline-block text-center font-bold uppercase tracking-widest shadow-lg ${
              isScrolled 
                ? 'bg-blue-600 text-white px-6 py-2 text-[10px] rounded-full shadow-blue-600/20' 
                : 'bg-white/10 backdrop-blur-md text-white border border-white/30 px-8 py-3 text-xs rounded-xl hover:bg-white/20'
            }`}
          >
            {isScrolled ? 'Join' : 'Join the Club'}
          </button>
        </div>
      </div>
    </nav>
  );
};

