import React, { useState, useEffect, useRef } from 'react';

interface HeaderProps {
  onContactClick?: (e?: React.MouseEvent) => void;
  isAdmin?: boolean;
}

const BRAND_CONFIG_KEY = 'dream_it_brand_config_v2';

interface BrandConfig {
  logo1: string | null;
  logo2: string | null;
  scale: number;
}

const Header: React.FC<HeaderProps> = ({ onContactClick, isAdmin = false }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [config, setConfig] = useState<BrandConfig>({
    logo1: null,
    logo2: null,
    scale: 100,
  });

  const fileInputRef1 = useRef<HTMLInputElement>(null);
  const fileInputRef2 = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);

    // Load brand configuration
    const savedConfig = localStorage.getItem(BRAND_CONFIG_KEY);
    if (savedConfig) {
      try {
        setConfig(JSON.parse(savedConfig));
      } catch (e) {
        console.error("Failed to load brand config", e);
      }
    }

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const saveConfig = (newConfig: BrandConfig) => {
    setConfig(newConfig);
    localStorage.setItem(BRAND_CONFIG_KEY, JSON.stringify(newConfig));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, slot: 1 | 2) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        const newConfig = { ...config };
        if (slot === 1) newConfig.logo1 = base64;
        else newConfig.logo2 = base64;
        saveConfig(newConfig);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetLogo = (slot: 1 | 2) => {
    if (window.confirm(`Reset Logo ${slot} to default?`)) {
      const newConfig = { ...config };
      if (slot === 1) newConfig.logo1 = null;
      else newConfig.logo2 = null;
      saveConfig(newConfig);
    }
  };

  const handleScaleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    saveConfig({ ...config, scale: parseInt(e.target.value) });
  };

  // Base sizes adjusted by the scale percentage
  const getLogoHeight = () => {
    const base = isScrolled ? 48 : 80;
    return (base * (config.scale / 100));
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-500 ${isScrolled ? 'bg-glass py-2 shadow-sm border-b border-slate-200/50' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 grid grid-cols-3 items-center">

        {/* Left Spacing / Admin Reset Controls */}
        <div className="flex flex-col gap-1 items-start">
           {isAdmin && (config.logo1 || config.logo2) && (
             <div className="flex flex-col gap-1">
               {config.logo1 && (
                 <button onClick={() => resetLogo(1)} className="text-[9px] font-bold uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1.5">
                   <i className="fas fa-undo-alt"></i> Reset L1
                 </button>
               )}
               {config.logo2 && (
                 <button onClick={() => resetLogo(2)} className="text-[9px] font-bold uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1.5">
                   <i className="fas fa-undo-alt"></i> Reset L2
                 </button>
               )}
             </div>
           )}
        </div>

        {/* Strategic Logo Placement (Dual Centered) */}
        <div className="flex flex-col items-center justify-center">
          <div className="flex items-center justify-center gap-4 md:gap-8">

            {/* Logo Slot 1 */}
            <div className="relative group">
              {config.logo1 ? (
                <img 
                  src={config.logo1} 
                  alt="Brand Logo 1" 
                  style={{ height: `${getLogoHeight()}px` }}
                  className="object-contain transition-all duration-300"
                />
              ) : (
                <div className="flex flex-col items-center">
                   <div className={`flex items-center justify-center rounded-full font-bold text-white transition-all duration-500 shadow-xl ${isScrolled ? 'w-10 h-10 bg-blue-600 text-lg' : 'w-16 h-16 bg-blue-600/90 text-2xl backdrop-blur-md border border-white/20'}`}>
                    D
                  </div>
                </div>
              )}
              {isAdmin && (
                <button 
                  onClick={() => fileInputRef1.current?.click()}
                  className="absolute -right-2 -top-2 w-6 h-6 bg-white text-blue-600 rounded-full shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all opacity-0 group-hover:opacity-100 z-50 border border-slate-100"
                  title="Upload Logo 1"
                >
                  <i className="fas fa-camera text-[10px]"></i>
                </button>
              )}
              <input type="file" ref={fileInputRef1} onChange={(e) => handleLogoUpload(e, 1)} className="hidden" accept="image/*" />
            </div>

            {/* Logo Slot 2 */}
            <div className="relative group">
              {config.logo2 ? (
                <img 
                  src={config.logo2} 
                  alt="Brand Logo 2" 
                  style={{ height: `${getLogoHeight()}px` }}
                  className="object-contain transition-all duration-300"
                />
              ) : (
                <div className="flex flex-col items-center">
                   <div className={`flex items-center justify-center rounded-full font-bold text-white transition-all duration-500 shadow-xl ${isScrolled ? 'w-10 h-10 bg-indigo-600 text-lg' : 'w-16 h-16 bg-indigo-600/90 text-2xl backdrop-blur-md border border-white/20'}`}>
                    M
                  </div>
                </div>
              )}
              {isAdmin && (
                <button 
                  onClick={() => fileInputRef2.current?.click()}
                  className="absolute -right-2 -top-2 w-6 h-6 bg-white text-blue-600 rounded-full shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all opacity-0 group-hover:opacity-100 z-50 border border-slate-100"
                  title="Upload Logo 2"
                >
                  <i className="fas fa-plus text-[10px]"></i>
                </button>
              )}
              <input type="file" ref={fileInputRef2} onChange={(e) => handleLogoUpload(e, 2)} className="hidden" accept="image/*" />
            </div>

          </div>

          {/* Sizing Controller (Admin Only) */}
          {isAdmin && (
            <div className="absolute top-full mt-4 bg-white/90 backdrop-blur-md border border-slate-200 p-3 rounded-2xl shadow-2xl flex items-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity z-[60]">
