               <input 
                type="range" 
                min="50" 
                max="200" 
                value={config.scale} 
                onChange={handleScaleChange}
                className="w-32 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
               />
               <span className="text-[10px] font-bold text-blue-600 min-w-[30px]">{config.scale}%</span>
            </div>
          )}

          {!isScrolled && !config.logo1 && !config.logo2 && (
            <span className="text-white text-[10px] font-bold uppercase tracking-[0.4em] mt-3 opacity-80">Dream it marketing</span>
          )}
        </div>

        {/* Action Button */}
        <div className="flex justify-end">
          <button 
            onClick={onContactClick}
            className={`transition-all duration-500 transform hover:scale-105 inline-block text-center font-bold uppercase tracking-widest shadow-lg ${
              isScrolled 
                ? 'bg-blue-600 text-white px-6 py-2 text-[10px] rounded-full shadow-blue-600/20' 
                : 'bg-white/10 backdrop-blur-md text-white border border-white/30 px-8 py-3 text-xs rounded-xl hover:bg-white/20'
            }`}
          >
            {isScrolled ? 'Join' : 'Join the Club'}
          </button>
        </div>
      </div>
    </nav>
  );
};

