import React, { useState, useEffect, useRef } from 'react';

interface HeaderProps {
  onContactClick?: (e?: React.MouseEvent) => void;
  isAdmin?: boolean;
}

const BRAND_CONFIG_KEY = 'dream_it_brand_config_v2';

interface BrandConfig {
  logo1: string | null;
  logo2: string | null;
  scale: number;
}

const Header: React.FC<HeaderProps> = ({ onContactClick, isAdmin = false }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [showDesignPanel, setShowDesignPanel] = useState(false);
  const [config, setConfig] = useState<BrandConfig>({
    logo1: null,
    logo2: null,
    scale: 100,
  });

  const fileInputRef1 = useRef<HTMLInputElement>(null);
  const fileInputRef2 = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });

    // Load brand configuration
    const savedConfig = localStorage.getItem(BRAND_CONFIG_KEY);
    if (savedConfig) {
      try {
        setConfig(JSON.parse(savedConfig));
      } catch (e) {
        console.error("Failed to load brand config", e);
      }
    }

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const saveConfig = (newConfig: BrandConfig) => {
    setConfig(newConfig);
    localStorage.setItem(BRAND_CONFIG_KEY, JSON.stringify(newConfig));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, slot: 1 | 2) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        const newConfig = { ...config };
        if (slot === 1) newConfig.logo1 = base64;
        else newConfig.logo2 = base64;
        saveConfig(newConfig);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetLogo = (slot: 1 | 2) => {
    if (window.confirm(`Reset Logo ${slot} to default?`)) {
      const newConfig = { ...config };
      if (slot === 1) newConfig.logo1 = null;
      else newConfig.logo2 = null;
      saveConfig(newConfig);
    }
  };

  const handleScaleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    saveConfig({ ...config, scale: parseInt(e.target.value) });
  };

  /**
   * Calculates the dynamic logo height based on scroll state and user scale preference.
   * Scrolled state significantly reduces the base size to satisfy the 'shrink' requirement.
   */
  const getLogoHeight = () => {
    // Unscrolled: base 90px | Scrolled: base 36px (60% reduction)
    const base = isScrolled ? 36 : 90;
    return (base * (config.scale / 100));
  };

  /**
   * Helper to get placeholder dimensions that scale with the images.
   */
  const getPlaceholderSize = () => {
    const base = isScrolled ? 32 : 80;
    return (base * (config.scale / 100));
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-700 ease-in-out ${isScrolled ? 'bg-glass py-2 shadow-sm border-b border-slate-200/50' : 'bg-transparent py-8'}`}>
      <div className="max-w-7xl mx-auto px-6 grid grid-cols-3 items-center">

        {/* Left Spacing / Admin Tools */}
        <div className="flex items-center gap-4">
           {isAdmin && (
             <div className="flex items-center gap-3">
               <button 
                onClick={() => setShowDesignPanel(!showDesignPanel)}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-all border ${showDesignPanel ? 'bg-blue-600 text-white border-blue-600 shadow-lg' : 'bg-white/10 text-slate-400 border-slate-200/20 hover:bg-white/20 hover:text-white'}`}
                title="Logo Design Panel"
               >
                 <i className="fas fa-palette text-sm"></i>
               </button>

               {showDesignPanel && (
                 <div className="flex flex-col gap-1 border-l border-slate-200/20 pl-4 animate-[fadeIn_0.3s_ease-out]">
                   {config.logo1 && (
                     <button onClick={() => resetLogo(1)} className="text-[9px] font-bold uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1.5 whitespace-nowrap">
                       <i className="fas fa-trash-alt"></i> Clear L1
                     </button>
                   )}
                   {config.logo2 && (
                     <button onClick={() => resetLogo(2)} className="text-[9px] font-bold uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1.5 whitespace-nowrap">
                       <i className="fas fa-trash-alt"></i> Clear L2
                     </button>
                   )}
                 </div>
               )}
             </div>
           )}
        </div>

        {/* Strategic Logo Placement (Dual Centered with Dynamic Scaling) */}
        <div className="flex flex-col items-center justify-center">
          <div className="flex items-center justify-center transition-all duration-500 gap-4 md:gap-8 transform-gpu">

            {/* Logo Slot 1 */}
            <div className="relative group flex items-center justify-center">
              {config.logo1 ? (
                <img 
                  src={config.logo1} 
                  alt="Brand Logo 1" 
                  style={{ height: `${getLogoHeight()}px` }}
                  className="object-contain transition-all duration-700 ease-[cubic-bezier(0.4,0,0.2,1)] will-change-[height]"
                />
              ) : (
                <div 
                  style={{ width: `${getPlaceholderSize()}px`, height: `${getPlaceholderSize()}px` }}
                  className={`flex flex-col items-center justify-center rounded-2xl border-2 border-dashed transition-all duration-700 ease-in-out ${isScrolled ? 'border-blue-600/20 bg-blue-600/5' : 'border-white/20 bg-white/5'}`}
                >
                   {isAdmin ? (
                     <button onClick={() => fileInputRef1.current?.click()} className="text-xs font-bold text-white/40 hover:text-white transition-colors flex flex-col items-center">
                       <i className="fas fa-plus mb-1"></i>
                       <span className="text-[8px] uppercase tracking-tighter">L1</span>
                     </button>
                   ) : (
                     <div className="w-1/2 h-1/2 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-sm">D</div>
                   )}
                </div>
              )}
              {isAdmin && config.logo1 && (
                <button 
                  onClick={() => fileInputRef1.current?.click()}
                  className="absolute -right-2 -top-2 w-6 h-6 bg-white text-blue-600 rounded-full shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all opacity-0 group-hover:opacity-100 z-50 border border-slate-100"
                  title="Replace Logo 1"
                >
                  <i className="fas fa-sync-alt text-[10px]"></i>
                </button>
              )}
              <input type="file" ref={fileInputRef1} onChange={(e) => handleLogoUpload(e, 1)} className="hidden" accept="image/*" />
            </div>

            {/* Logo Slot 2 */}
            <div className="relative group flex items-center justify-center">
              {config.logo2 ? (
                <img 
                  src={config.logo2} 
                  alt="Brand Logo 2" 
                  style={{ height: `${getLogoHeight()}px` }}
                  className="object-contain transition-all duration-700 ease-[cubic-bezier(0.4,0,0.2,1)] will-change-[height]"
                />
              ) : (
                <div 
                  style={{ width: `${getPlaceholderSize()}px`, height: `${getPlaceholderSize()}px` }}
                  className={`flex flex-col items-center justify-center rounded-2xl border-2 border-dashed transition-all duration-700 ease-in-out ${isScrolled ? 'border-indigo-600/20 bg-indigo-600/5' : 'border-white/20 bg-white/5'}`}
                >
                   {isAdmin ? (
                     <button onClick={() => fileInputRef2.current?.click()} className="text-xs font-bold text-white/40 hover:text-white transition-colors flex flex-col items-center">
                       <i className="fas fa-plus mb-1"></i>
                       <span className="text-[8px] uppercase tracking-tighter">L2</span>
                     </button>
                   ) : (
                     <div className="w-1/2 h-1/2 bg-indigo-600 rounded-full flex items-center justify-center text-white font-bold text-sm">M</div>
                   )}
                </div>
              )}
              {isAdmin && config.logo2 && (
                <button 
                  onClick={() => fileInputRef2.current?.click()}
                  className="absolute -right-2 -top-2 w-6 h-6 bg-white text-indigo-600 rounded-full shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all opacity-0 group-hover:opacity-100 z-50 border border-slate-100"
                  title="Replace Logo 2"
                >
                  <i className="fas fa-sync-alt text-[10px]"></i>
                </button>
              )}
              <input type="file" ref={fileInputRef2} onChange={(e) => handleLogoUpload(e, 2)} className="hidden" accept="image/*" />
            </div>

          </div>

          {/* Sizing & Design Panel (Admin Only) */}
          {isAdmin && showDesignPanel && (
            <div className="absolute top-full mt-6 bg-white rounded-3xl shadow-2xl p-6 border border-slate-100 min-w-[280px] animate-[slideUp_0.3s_ease-out] z-[60]">
               <div className="flex items-center justify-between mb-6">
                 <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Logo Scale Controller</h4>
                 <button onClick={() => setShowDesignPanel(false)} className="text-slate-300 hover:text-slate-500">
                   <i className="fas fa-times text-xs"></i>
                 </button>
               </div>

               <div className="space-y-6">
                 <div className="flex flex-col gap-4">
                    <div className="flex justify-between items-center">
                      <span className="text-[9px] font-bold text-blue-600 uppercase tracking-widest">Global Size Preference</span>
                      <span className="text-xs font-black text-slate-900">{config.scale}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="20" 
                      max="400" 
                      value={config.scale} 
                      onChange={handleScaleChange}
                      className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <div className="flex justify-between text-[8px] text-slate-400 font-bold uppercase tracking-tighter">
                      <span>Tiny</span>
                      <span>Default</span>
                      <span>Enormous</span>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-3 pt-4 border-t border-slate-50">
                    <button onClick={() => fileInputRef1.current?.click()} className="py-2 bg-slate-50 hover:bg-slate-100 rounded-xl text-[9px] font-bold uppercase text-slate-600 transition-colors">
                      <i className="fas fa-image mr-1"></i> Update L1
                    </button>
                    <button onClick={() => fileInputRef2.current?.click()} className="py-2 bg-slate-50 hover:bg-slate-100 rounded-xl text-[9px] font-bold uppercase text-slate-600 transition-colors">
                      <i className="fas fa-image mr-1"></i> Update L2
                    </button>
                 </div>
               </div>
            </div>
          )}

          {!isScrolled && !config.logo1 && !config.logo2 && (
            <span className="text-white text-[10px] font-bold uppercase tracking-[0.4em] mt-3 opacity-80 animate-[fadeIn_1s_ease-out]">Dream it marketing</span>
          )}
        </div>

        {/* Action Button */}
        <div className="flex justify-end">
          <button 
            onClick={onContactClick}
            className={`transition-all duration-700 transform hover:scale-105 inline-block text-center font-bold uppercase tracking-widest shadow-lg ${
              isScrolled 
                ? 'bg-blue-600 text-white px-6 py-2 text-[10px] rounded-full shadow-blue-600/20' 
                : 'bg-white/10 backdrop-blur-md text-white border border-white/30 px-8 py-3 text-xs rounded-xl hover:bg-white/20'
            }`}
          >
            {isScrolled ? 'Join' : 'Join the Club'}
          </button>
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(10px) scale(0.95); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}} />
    </nav>
  );
};

