import React, { useState, useEffect } from 'react';

interface HeroProps {
  onContactClick?: (e?: React.MouseEvent) => void;
}

const BRAND_CONFIG_KEY = 'dream_it_brand_config_v2';

const Hero: React.FC<HeroProps> = ({ onContactClick }) => {
  const [scrollY, setScrollY] = useState(0);
  const [logos, setLogos] = useState<{ logo1: string | null; logo2: string | null }>({ logo1: null, logo2: null });

  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });

    // Load logos
    const saved = localStorage.getItem(BRAND_CONFIG_KEY);
    if (saved) {
      try {
        const config = JSON.parse(saved);
        setLogos({ logo1: config.logo1, logo2: config.logo2 });
      } catch (e) {
        console.error("Failed to load logos for Hero", e);
      }
    }

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const LogoSignature = () => {
    const hasLogos = logos.logo1 || logos.logo2;
    if (!hasLogos) return <div className="mb-10" />;
    return (
      <div className="flex flex-col items-start gap-4 mb-6 md:mb-10 opacity-0 animate-[fadeInUp_1.5s_ease-out_0.2s_forwards]">
        <div className="flex items-center gap-4 md:gap-8">
          {logos.logo1 && (
            <img src={logos.logo1} alt="Logo 1" className="h-12 md:h-16 object-contain" />
          )}
          {logos.logo2 && (
            <img src={logos.logo2} alt="Logo 2" className="h-12 md:h-16 object-contain" />
          )}
        </div>
      </div>
    );
  };

  return (
    <section id="home" className="relative h-screen flex items-center overflow-hidden bg-slate-900">
      {/* 10-Second Cinematic "Scroll" Background */}
      <div 
        className="absolute inset-0 z-0"
        style={{ 
          transform: `translateY(${scrollY * 0.4}px)`,
          transition: 'transform 0.1s ease-out'
        }}
      >
        <div className="w-full h-full overflow-hidden">
          <img 
            src="https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=2000" 
            alt="Luxury Beach" 
            className="w-full h-full object-cover scale-110 animate-[cinematicScroll_15s_ease-in-out_infinite]"
          />
        </div>
      </div>

      {/* Overlays */}
      <div className="absolute inset-0 z-[1] bg-gradient-to-r from-black/80 via-black/40 to-transparent"></div>

      {/* Content - Left Aligned for classic luxury feel */}
      <div 
        className="relative z-10 w-full max-w-7xl mx-auto px-6"
        style={{ 
          transform: `translateY(${-scrollY * 0.05}px)`,
          transition: 'transform 0.1s ease-out'
        }}
      >
        <div className="max-w-4xl">
          <LogoSignature />

          <h1 className="text-6xl md:text-[10rem] text-white font-bold mb-8 leading-[0.9] drop-shadow-2xl animate-[fadeInUp_1.5s_ease-out_forwards]">
            The Luxury <br /> 
            of <span className="italic serif text-blue-300">Time.</span>
          </h1>

          <p className="text-xl md:text-3xl text-white/90 font-light tracking-wide drop-shadow-lg opacity-0 animate-[fadeInUp_1.5s_ease-out_0.5s_forwards] mb-12 max-w-2xl">
            Invest in your future memories with a lifetime ticket to the world's most serene shores.
          </p>

          <div className="opacity-0 animate-[fadeInUp_1.5s_ease-out_0.8s_forwards]">
             <button 
              onClick={onContactClick}
              className="bg-blue-600 hover:bg-blue-700 text-white px-12 py-5 rounded-full font-bold text-xl transition-all transform hover:scale-105 shadow-2xl shadow-blue-500/40 inline-block"
            >
              Join the Club
            </button>
          </div>
        </div>
      </div>

      {/* Discovery Indicator */}
      <div className="absolute bottom-12 left-6 z-20 flex flex-col items-start gap-4 opacity-0 animate-[fadeInUp_1.5s_ease-out_1.2s_forwards]">
        <span className="text-white/40 text-[10px] uppercase tracking-[0.3em] font-bold">Scroll to discover</span>
        <div className="w-[1px] h-16 bg-gradient-to-b from-blue-400 to-transparent animate-[scrollLine_2s_ease-in-out_infinite]"></div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes cinematicScroll {
          0% { transform: scale(1.1) translate(0, 0); }
          50% { transform: scale(1.2) translate(-1%, -1%); }
          100% { transform: scale(1.1) translate(0, 0); }
        }
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(40px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes scrollLine {
          0% { transform: scaleY(0); transform-origin: top; }
          50% { transform: scaleY(1); transform-origin: top; }
          51% { transform: scaleY(1); transform-origin: bottom; }
          100% { transform: scaleY(0); transform-origin: bottom; }
        }
      `}} />
    </section>
  );
};

export default Hero;

import React, { useState, useEffect } from 'react';

interface FooterProps {
  isAdmin?: boolean;
  onToggleAdmin?: () => void;
  onLegalClick?: (type: 'privacy' | 'terms') => void;
}

const SOCIAL_STORAGE_KEY = 'dream_it_social_links_v1';
const scriptURL = 'https://script.google.com/macros/s/AKfycbw82oR186SCMQlO1lCTrq37t7_NNjxIwEN90_kxm48AJiuxwT-cl48PEKr1LqNmgKir/exec';

const DEFAULT_SOCIALS = {
  facebook: 'https://www.facebook.com/DreamVacationsSA/',
  instagram: 'https://www.instagram.com/dreamvacations_sa/',
  tiktok: 'https://www.tiktok.com/@dreamvacations_sa'
};

const Footer: React.FC<FooterProps> = ({ isAdmin = false, onToggleAdmin, onLegalClick }) => {
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [showSocialEditor, setShowSocialEditor] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  // Social Links State
  const [socialLinks, setSocialLinks] = useState(DEFAULT_SOCIALS);

  // Newsletter States
  const [email, setEmail] = useState('');
  const [subStatus, setSubStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [subError, setSubError] = useState('');

  // Load social links from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(SOCIAL_STORAGE_KEY);
    if (saved) {
      try {
        setSocialLinks(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load social links", e);
      }
    }
  }, []);

  const handleAdminClick = () => {
    if (isAdmin) {
      if (onToggleAdmin) onToggleAdmin();
    } else {
      setShowLoginModal(true);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === '072111') {
      if (onToggleAdmin) onToggleAdmin();
      setShowLoginModal(false);
      setPassword('');
      setError('');
    } else {
      setError('Invalid admin credentials.');
    }
  };

  const saveSocialLinks = (newLinks: typeof DEFAULT_SOCIALS) => {
    setSocialLinks(newLinks);
    localStorage.setItem(SOCIAL_STORAGE_KEY, JSON.stringify(newLinks));
  };

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubError('');

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setSubError('Please enter a valid email address.');
      return;
    }

    setSubStatus('loading');

    try {
      const payload = {
        name: 'Newsletter Subscriber',
        email: email,
        phone: 'N/A',
        interest: 'Newsletter Subscription',
        source: 'Footer Newsletter',
        timestamp: new Date().toLocaleString(),
        dream: 'Wants to stay updated on luxury resort collections.'
      };

      await fetch(scriptURL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(payload),
      });

      setSubStatus('success');
      setEmail('');
    } catch (err) {
      setSubStatus('error');
      setSubError('Connection failed. Please check your internet and try again.');
    }
  };

  return (
    <footer className="bg-slate-900 text-slate-400 py-16 border-t border-slate-800 relative">
      <div className="max-w-7xl mx-auto px-6">
        <div className="grid md:grid-cols-2 gap-16 mb-16 text-center md:text-left">
          {/* Brand Column */}
          <div className="max-w-md mx-auto md:mx-0">
             <div className="flex items-center justify-center md:justify-start mb-6">
              <span className="text-sm font-bold text-white tracking-widest uppercase opacity-40">Accredited Agents</span>
            </div>
            <p className="text-sm leading-relaxed text-slate-400">
              Your lifetime ticket to investing more time into your holidays, when you need them, and where you want them.
            </p>
          </div>

          {/* Newsletter Column */}
          <div className="max-w-sm mx-auto md:ml-auto md:mr-0 w-full">
            <h4 className="text-white font-bold mb-6 text-sm uppercase tracking-widest">Newsletter</h4>
            <p className="text-sm mb-6 text-slate-400">Get the latest travel inspiration and exclusive resort news delivered to your inbox.</p>

            {subStatus === 'success' ? (
              <div className="bg-blue-600/10 border border-blue-500/30 rounded-xl p-6 text-center animate-[fadeIn_0.5s_ease-out]">
                <div className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center mx-auto mb-3 shadow-lg shadow-blue-500/20">
                  <i className="fas fa-check"></i>
                </div>
                <h5 className="text-white font-bold text-sm">Welcome to the Club!</h5>
                <p className="text-[11px] text-blue-300 mt-2 leading-relaxed">
                  We've initiated your welcome note. <br />
                  <span className="text-white font-bold underline decoration-blue-500/50">IMPORTANT: Please check your Spam/Promotions folder</span> and mark us as "Not Spam" to ensure you get our updates.
                </p>
                <button 
                  onClick={() => setSubStatus('idle')}
                  className="mt-4 text-[10px] text-slate-500 hover:text-white uppercase font-bold tracking-widest transition-colors"
                >
                  Add another email
                </button>
              </div>
            ) : (
              <form onSubmit={handleSubscribe} className="space-y-3">
                <div className="flex w-full group relative">
                  <input 
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Your email address" 
                    disabled={subStatus === 'loading'}
                    className={`bg-slate-800 border ${subError ? 'border-red-500' : 'border-slate-700'} rounded-l-xl px-5 py-3 w-full focus:ring-1 focus:ring-blue-500 text-white text-sm outline-none transition-all disabled:opacity-50`} 
                  />
                  <button 
                    type="submit"
                    disabled={subStatus === 'loading'}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-r-xl transition-colors shadow-lg shadow-blue-900/20 disabled:bg-slate-700 flex items-center justify-center min-w-[60px]"
                  >
                    {subStatus === 'loading' ? (
                      <i className="fas fa-circle-notch animate-spin"></i>
                    ) : (
                      <i className="fas fa-paper-plane"></i>
                    )}
                  </button>
                </div>
                {subError && (
                  <p className="text-red-400 text-[11px] font-medium flex items-center gap-1.5 animate-[fadeIn_0.3s_ease-out]">
                    <i className="fas fa-exclamation-circle"></i> {subError}
                  </p>
                )}
                <p className="text-[10px] text-slate-500 mt-2 italic">
                  Expect a response shortly.
                </p>
              </form>
            )}
          </div>
        </div>

        <div className="pt-8 border-t border-slate-800/50 flex flex-col md:flex-row justify-between items-center text-[11px] gap-6">
          <div className="flex flex-col md:flex-row items-center gap-4 md:gap-8">
            <p className="text-slate-500 uppercase tracking-wider font-medium">© 2026. ACCREDITED AGENTS of the Dream Vacation club.</p>
            <div className="flex space-x-6">
              <button onClick={() => onLegalClick?.('privacy')} className="hover:text-white transition-colors">Privacy Policy</button>
