            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="flex items-center space-x-5 text-base">
              <a href={socialLinks.facebook} target="_blank" rel="noopener noreferrer" className="text-slate-500 hover:text-white transition-colors">
