                  <i className="fas fa-cog"></i>
                </button>
              )}
            </div>

            <button 
              onClick={handleAdminClick}
              className={`px-4 py-1.5 rounded-full border text-[10px] font-bold uppercase tracking-widest transition-all ${isAdmin ? 'bg-blue-600/10 text-blue-400 border-blue-400/50' : 'border-slate-700 hover:border-slate-500 text-slate-500'}`}
