                  type="url" 
                  value={socialLinks.tiktok}
                  onChange={(e) => saveSocialLinks({ ...socialLinks, tiktok: e.target.value })}
                  placeholder="https://tiktok.com/@..."
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs outline-none focus:border-blue-500 transition-colors"
                />
              </div>
            </div>
            <div className="mt-6 flex justify-end">
              <button 
                onClick={() => setShowSocialEditor(false)}
                className="text-[10px] font-bold uppercase tracking-widest text-blue-400 hover:text-blue-300 transition-colors"
              >
                Close Editor
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Admin Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-w-sm w-full shadow-2xl animate-[fadeInUp_0.3s_ease-out]">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-2xl mx-auto mb-4">
                <i className="fas fa-user-shield"></i>
              </div>
              <h3 className="text-2xl font-bold text-slate-900">Admin Login</h3>
              <p className="text-slate-500 text-sm mt-1">Please enter your management password</p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
              <div>
                <input 
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
