export default Hero;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';

interface VoiceConciergeProps {
  onClose: () => void;
}

const VoiceConcierge: React.FC<VoiceConciergeProps> = ({ onClose }) => {
  const [isActive, setIsActive] = useState(false);
  const [status, setStatus] = useState('Initializing...');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Helper functions for audio processing
  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const createBlob = (data: Float32Array) => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const cleanup = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    sourcesRef.current.forEach(s => {
      try { s.stop(); } catch(e) {}
    });
    sourcesRef.current.clear();
    setIsActive(false);
    setIsSpeaking(false);
  }, []);

  const startSession = async () => {
    cleanup();
    setError(null);
    setStatus('Connecting to Elena...');

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        throw new Error("API Key is missing. Please check your environment variables.");
      }

      const ai = new GoogleGenAI({ apiKey });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            setStatus('Elena is listening...');

            if (audioContextRef.current) {
              const source = audioContextRef.current.createMediaStreamSource(stream);
              const scriptProcessor = audioContextRef.current.createScriptProcessor(4096, 1, 1);

              scriptProcessor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmBlob = createBlob(inputData);
                sessionPromise.then((session) => {
                  if (session) session.sendRealtimeInput({ media: pcmBlob });
                });
              };

              source.connect(scriptProcessor);
              scriptProcessor.connect(audioContextRef.current.destination);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const parts = message.serverContent?.modelTurn?.parts;
            const base64Audio = parts?.[0]?.inlineData?.data;

            if (base64Audio && outputAudioContextRef.current) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);

              const audioBuffer = await decodeAudioData(
                decode(base64Audio),
                outputAudioContextRef.current,
                24000,
                1
              );

              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContextRef.current.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => {
                try { s.stop(); } catch(e) {}
              });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => {
            console.error("Live API Error Event:", e);
            setError("Connection encountered an error.");
            setStatus('Elena disconnected.');
            setIsActive(false);
          },
          onclose: (e) => {
            console.log("Live API Closed:", e);
            if (!error) setStatus('Elena is resting.');
            setIsActive(false);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
          },
          systemInstruction: `
            You are "Elena", the elite virtual concierge for "Dream it marketing".
            Your tone is sophisticated, warm, and highly professional.
            You represent an exclusive vacation club with resorts like Mount Amanzi, Finfoot, Alpine Heath, Blue Marlin, and The Peninsula.
            Your goal is to help prospective members understand how we give them back "The Luxury of Time".
            Be concise, helpful, and welcoming.
          `,
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      console.error("Elena Initialization Error:", err);
      setError(err.message || "Failed to start the concierge session.");
      setStatus('Elena is unavailable.');
    }
  };

  useEffect(() => {
    startSession();
    return () => cleanup();
  }, []);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-3xl" onClick={onClose}></div>

      <div className="relative w-full max-w-xl text-center">
        <button 
          onClick={onClose}
          className="absolute -top-16 right-0 w-12 h-12 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center text-white transition-all z-50"
        >
          <i className="fas fa-times"></i>
        </button>

        <div className="space-y-12">
          {/* Animated Waveform / Aura */}
          <div className="relative flex justify-center items-center h-64">
            <div className={`absolute w-48 h-48 bg-blue-500/20 rounded-full blur-3xl transition-all duration-1000 ${isSpeaking ? 'scale-150 opacity-60' : 'scale-100 opacity-20'}`}></div>
            <div className={`absolute w-32 h-32 bg-blue-600/40 rounded-full blur-2xl transition-all duration-500 ${isSpeaking ? 'scale-125' : 'scale-100'}`}></div>

            {/* Visualizer bars */}
            <div className="flex items-end gap-1.5 h-16 relative z-10">
              {[...Array(12)].map((_, i) => (
                <div 
                  key={i} 
                  className={`w-1.5 rounded-full bg-blue-400 transition-all duration-150 ${isActive ? (isSpeaking ? 'animate-bounce' : 'animate-pulse') : 'h-2 opacity-20'}`}
                  style={{ 
                    height: isActive ? `${Math.random() * 100 + 20}%` : '8px',
                    animationDelay: `${i * 0.1}s`,
                    animationDuration: isSpeaking ? '0.5s' : '1.5s'
                  }}
                ></div>
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <h2 className="text-white text-5xl font-bold serif tracking-tight">Meet Elena</h2>
              <p className="text-blue-400 font-bold uppercase tracking-[0.2em] text-xs">Your Private Travel Concierge</p>
            </div>

            <div className="flex flex-col items-center gap-4">
              <div className="bg-white/5 border border-white/10 px-6 py-3 rounded-full inline-block backdrop-blur-md">
                <span className="text-white/80 text-sm flex items-center gap-3 font-medium">
                  <span className={`w-2.5 h-2.5 rounded-full ${isActive ? 'bg-green-500 shadow-[0_0_12px_rgba(34,197,94,0.6)] animate-pulse' : 'bg-red-500'}`}></span>
                  {status}
                </span>
              </div>

              {!isActive && !status.includes('Connecting') && (
                <button 
                  onClick={startSession}
                  className="px-8 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-full text-xs font-bold uppercase tracking-widest transition-all shadow-lg shadow-blue-600/20"
                >
                  Reconnect Elena
                </button>
              )}
            </div>
          </div>

          {error && (
            <div className="max-w-xs mx-auto p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-[10px] uppercase font-bold tracking-wider animate-pulse">
              <i className="fas fa-exclamation-triangle mr-2"></i>
              {error}
            </div>
          )}

          <div className="text-white/40 text-sm max-w-sm mx-auto leading-relaxed italic px-4">
            "I'm here to help you reclaim your future memories. Ask me about our coastal escapes or safari lodges."
          </div>

          <button 
            onClick={onClose}
            className="text-white/20 hover:text-white transition-colors uppercase tracking-[0.3em] text-[10px] font-black"
          >
            End Conversation
          </button>
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes bounce {
          0%, 100% { transform: scaleY(1); }
          50% { transform: scaleY(2.5); }
        }
      `}} />
    </div>
  );
};

